import jax.numpy as jnp
import flax.linen as nn
from jax import random
from typing import Dict, Any

class SimpleCNN(nn.Module):
    """A simple 1D CNN for RNA sequence modeling."""
    d_output: int
    task_type: str
    hidden_dim: int = 128
    dropout_rate: float = 0.2

    @nn.compact
    def __call__(self, x, deterministic=True):
        x = nn.Conv(features=self.hidden_dim, kernel_size=(5,), padding='SAME')(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = nn.Conv(features=self.hidden_dim * 2, kernel_size=(5,), padding='SAME')(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = jnp.mean(x, axis=1)

        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class CNNetworkWrapper:
    def __init__(self, d_output: int, task_type: str, hidden_dim: int, dropout_rate: float):
        self.network = SimpleCNN(d_output=d_output, task_type=task_type, hidden_dim=hidden_dim, dropout_rate=dropout_rate)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if not deterministic and rng_key is None:
            rng_key = random.PRNGKey(0)

        return self.network.apply(
            {'params': params}, 
            x, 
            deterministic=deterministic, 
            rngs={'dropout': rng_key} if not deterministic else None
        )

def create_network(hparams: Dict[str, Any]):
    return CNNetworkWrapper(
        d_output=hparams.get("d_output"),
        task_type=hparams.get("task_type"),
        hidden_dim=hparams.get("hidden_dim"),
        dropout_rate=hparams.get("dropout_rate")
    )

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 128,
        'dropout_rate': 0.2
    }
